package com.friendinneed.routine; import com.friendinneed.consent.*;import com.friendinneed.profile.*;import com.friendinneed.security.UserRepository;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.access.AccessDeniedException;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/profiles/{profileId}/routines") public class RoutineController{private final RoutineService service;private final ConsentService consent;private final CompanionProfileRepository profiles;private final UserRepository users;public RoutineController(RoutineService s,ConsentService c,CompanionProfileRepository p,UserRepository u){service=s;consent=c;profiles=p;users=u;}private void owner(UUID p){String name=SecurityContextHolder.getContext().getAuthentication().getName();if(!users.findByUsername(name).orElseThrow(()->new AccessDeniedException("Authentication is required")).getId().equals(profiles.findById(p).orElseThrow(()->new AccessDeniedException("Profile not found")).getUserId()))throw new AccessDeniedException("Access denied");}private void allowed(UUID p){owner(p);if(!consent.isEnabled(p,IntegrationType.SMART_HOME))throw new org.springframework.security.access.AccessDeniedException("Smart home consent is required");}@GetMapping List<Routine> list(@PathVariable UUID profileId){allowed(profileId);return service.list(profileId);}@PostMapping @ResponseStatus(HttpStatus.CREATED) Routine create(@PathVariable UUID profileId,@RequestBody Request r){allowed(profileId);return service.create(profileId,r.triggerPhrase(),r.steps());}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID profileId,@PathVariable UUID id){allowed(profileId);service.delete(profileId,id);}record Request(String triggerPhrase,List<Map<String,Object>> steps){}}
